// تجميع إحصائيات توليد المحتوى اليومي
const items = $input.all();
const totalGenerated = items.length;
const avgScore = items.length > 0
  ? Math.round(items.reduce((s, i) => s + (i.json.content_score || 0), 0) / items.length)
  : 0;

return [{
  json: {
    total_generated: totalGenerated,
    avg_score: avgScore,
    generated_date: new Date().toISOString().split('T')[0],
    summary: `تم توليد ${totalGenerated} منشور بمتوسط نقاط ${avgScore}/100`,
    ready_for_f8: true
  }
}];

